function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  historyUrl: 'https://httpbin.org/post',
  aiUrl: 'https://httpbin.org/post',
  actionUrl: 'https://httpbin.org/post',
  crmUrl: 'https://httpbin.org/post',
  timeoutMs: 20000,
  // Collection strategy thresholds
  policies: {
    softDays: 15,
    firmDays: 30,
    hardDays: 60,
    highValue: 5000
  },
  allowSimulation: true
};

const hook = ref('Webhook - Collection Request');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const collectionId = String(body.collectionId || body.id || ('COL-' + Date.now())).trim();
const invoiceId = String(body.invoiceId || body.invoice_id || '').trim();
const customerId = String(body.customerId || body.customer_id || '').trim();
const customerName = String(body.customerName || body.name || 'Customer').trim();
const email = String(body.email || body.customerEmail || '').trim();
const amount = Number(body.amount || body.balance || 0);
const currency = String(body.currency || 'USD').toUpperCase();
const daysOverdue = Number(body.daysOverdue || body.overdueDays || 0);
const previousPromises = Number(body.previousPromises || 0);
const lastContactDays = Number(body.lastContactDays || 999);

if (!invoiceId) errors.push('invoiceId is required');
if (!customerId) errors.push('customerId is required');
if (!Number.isFinite(amount) || amount <= 0) errors.push('amount must be a positive number');
if (!email) errors.push('email is required');

const valid = errors.length === 0;

// Determine severity tier
let severity = 'soft';
if (daysOverdue >= CONFIG.policies.hardDays || amount >= CONFIG.policies.highValue) severity = 'hard';
else if (daysOverdue >= CONFIG.policies.firmDays) severity = 'firm';

const context = {
  collectionId,
  invoiceId,
  customerId,
  customerName,
  email,
  amount,
  currency,
  daysOverdue,
  previousPromises,
  lastContactDays,
  severity
};

let historyUrl = CONFIG.historyUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  historyUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    context,
    urls: {
      history: historyUrl,
      ai: CONFIG.aiUrl,
      action: CONFIG.actionUrl,
      crm: CONFIG.crmUrl
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const ctx = ref('Code - Validate & Build Customer Context');
const histRes = ref('HTTP Request - Fetch Customer History') || {};
const aiRes = ref('HTTP Request - AI Generate Actions') || {};
const actionRes = ref('HTTP Request - Execute Primary Action') || {};
const crmRes = ref('HTTP Request - Update AR / CRM') || {};

function statusOf(res) {
  return Number(res.statusCode) || 0;
}

const histOk = statusOf(histRes) >= 200 && statusOf(histRes) < 300;
const aiOk = statusOf(aiRes) >= 200 && statusOf(aiRes) < 300;
const actionOk = statusOf(actionRes) >= 200 && statusOf(actionRes) < 300;
const crmOk = statusOf(crmRes) >= 200 && statusOf(crmRes) < 300;

// Simulated AI output (in real use parse aiRes.body)
const aiActions = [
  {
    rank: 1,
    type: 'email',
    channel: 'email',
    subject: `Friendly reminder – Invoice ${ctx.context.invoiceId}`,
    tone: ctx.context.severity === 'soft' ? 'friendly' : (ctx.context.severity === 'firm' ? 'professional' : 'firm'),
    expectedSuccess: 0.62
  },
  {
    rank: 2,
    type: 'call',
    channel: 'phone',
    scriptHint: 'Offer payment plan if needed',
    expectedSuccess: 0.48
  },
  {
    rank: 3,
    type: 'offer',
    channel: 'email',
    description: '2% early-settlement discount valid 7 days',
    expectedSuccess: 0.35
  }
];

const primaryAction = aiActions[0];

const plan = {
  collectionId: ctx.context.collectionId,
  customer: {
    id: ctx.context.customerId,
    name: ctx.context.customerName,
    email: ctx.context.email,
    severity: ctx.context.severity,
    daysOverdue: ctx.context.daysOverdue,
    amount: ctx.context.amount,
    currency: ctx.context.currency
  },
  enrichment: {
    historyFetched: histOk,
    statusCode: statusOf(histRes)
  },
  ai: {
    generated: aiOk,
    statusCode: statusOf(aiRes),
    actions: aiActions,
    primary: primaryAction
  },
  execution: {
    primaryExecuted: actionOk,
    statusCode: statusOf(actionRes),
    crmUpdated: crmOk,
    crmStatusCode: statusOf(crmRes)
  },
  nextSteps: [
    `Monitor response for 3 business days`,
    `If no reply → escalate to rank-2 action (call)`,
    `Update promise-to-pay if customer responds`
  ],
  generatedAt: new Date().toISOString()
};

const httpStatus = (aiOk && actionOk) ? 200 : 207;

return [{
  json: {
    httpStatus,
    body: plan,
    collectionId: ctx.context.collectionId
  }
}];
